import{n as e}from"./rolldown-runtime-Cyuzqnbw.js";import{A as t}from"./framer-Be3hPn0e.js";import{On as n,Rn as r,Wr as i,it as a,t as o}from"./icons-DTR6_mEc.js";import{n as s,t as c}from"./ArticleLayout-oYmAtQSh.js";var l,u,d=e((()=>{o(),l=[{"@context":`https://schema.org`,"@type":`Article`,headline:`Véhicule ou permis étranger : rouler assuré en France`,description:`Véhicule à plaque étrangère ou retour de l'étranger ? Roulez assuré en France le temps de l'immatriculer. Assurance temporaire, attestation immédiate, 1 à 90 jours.`,author:{"@type":`Organization`,name:`Evidence Assurances`},publisher:{"@type":`Organization`,name:`AssuTempo`,logo:{"@type":`ImageObject`,url:`https://assutempo.fr/logo.png`}},mainEntityOfPage:`https://assutempo.fr/articles/assurance-temporaire-vehicule-etranger-france`,datePublished:`2026-06-03`,dateModified:`2026-06-03`},{"@context":`https://schema.org`,"@type":`BreadcrumbList`,itemListElement:[{"@type":`ListItem`,position:1,name:`Accueil`,item:`https://assutempo.fr`},{"@type":`ListItem`,position:2,name:`Articles`,item:`https://assutempo.fr/articles`},{"@type":`ListItem`,position:3,name:`Véhicule ou permis étranger en France`,item:`https://assutempo.fr/articles/assurance-temporaire-vehicule-etranger-france`}]},{"@context":`https://schema.org`,"@type":`HowTo`,name:`Assurer un véhicule étranger en France le temps de l'immatriculer`,step:[{"@type":`HowToStep`,position:1,name:`Souscrire une assurance temporaire`,text:`Souscrivez en ligne à partir de la plaque étrangère ou du numéro de châssis. Attestation immédiate.`},{"@type":`HowToStep`,position:2,name:`Rouler légalement`,text:`Circulez en France avec votre justificatif d'assurance et la carte grise étrangère.`},{"@type":`HowToStep`,position:3,name:`Lancer l'immatriculation`,text:`Demandez l'immatriculation française sur l'ANTS dans le mois si vous résidez en France.`},{"@type":`HowToStep`,position:4,name:`Obtenir la carte grise`,text:`Recevez un CPI ou une plaque WW pour la transition, puis la carte grise définitive.`}]},{"@context":`https://schema.org`,"@type":`FAQPage`,mainEntity:[{"@type":`Question`,name:`Peut-on rouler en France avec une plaque étrangère ?`,acceptedAnswer:{"@type":`Answer`,text:`Oui, temporairement et si vous êtes assuré. Si vous résidez en France, l'immatriculation française est obligatoire dans un délai d'un mois.`}},{"@type":`Question`,name:`Combien de temps peut-on garder une plaque étrangère ?`,acceptedAnswer:{"@type":`Answer`,text:`Jusqu'à un mois pour un résident. Au-delà, vous risquez une amende de 135 euros et devez avoir immatriculé le véhicule.`}},{"@type":`Question`,name:`Peut-on assurer un véhicule immatriculé à l'étranger ?`,acceptedAnswer:{"@type":`Answer`,text:`Oui, via une assurance temporaire de 1 à 90 jours, à partir de la plaque étrangère ou du numéro de châssis.`}},{"@type":`Question`,name:`Faut-il un permis français ?`,acceptedAnswer:{"@type":`Answer`,text:`Non, un permis valide et reconnu suffit. Les permis de l'Union européenne sont acceptés, les permis hors UE sous conditions.`}},{"@type":`Question`,name:`Quels documents pour souscrire ?`,acceptedAnswer:{"@type":`Answer`,text:`Carte grise étrangère ou preuve de propriété, permis valide, pièce d'identité, moyen de paiement.`}},{"@type":`Question`,name:`Que risque-t-on sans assurance ?`,acceptedAnswer:{"@type":`Answer`,text:`Un défaut d'assurance, délit passible d'une amende jusqu'à 3 750 euros, avec immobilisation possible.`}}]}],u={slug:`assurance-temporaire-vehicule-etranger-france`,seo:{title:`Véhicule ou permis étranger : assurance temporaire en France`,description:`Véhicule à plaque étrangère ou retour de l'étranger ? Roulez assuré en France le temps de l'immatriculer. Assurance temporaire, attestation immédiate, 1 à 90 jours.`,canonical:`https://assutempo.fr/articles/assurance-temporaire-vehicule-etranger-france`,jsonLd:l},category:`International`,readTime:`5 min`,updatedDate:`3 juin 2026`,author:`Evidence Assurances`,immediateAnswerLabel:`L'essentiel`,headline:`Véhicule ou permis étranger : rouler assuré en France`,immediateAnswer:`Un véhicule à plaque étrangère doit être assuré pour circuler en France, et si vous y résidez, immatriculé en France dans le mois suivant son arrivée ou son achat (article R322-5). En attendant l'immatriculation, une assurance temporaire, de 1 à 90 jours, vous couvre légalement avec une attestation immédiate, à partir de la plaque étrangère ou du numéro de châssis.`,sections:[{type:`text`,heading:`Peut-on rouler en France avec un véhicule étranger ?`,paragraphs:[`Oui, mais temporairement et sous conditions. Vous pouvez circuler avec la plaque d'origine à condition d'être assuré. Si vous résidez en France, vous devez demander l'immatriculation française dans un délai d'un mois après l'importation ou l'achat (article R322-5). Cette règle ne vise pas les non-résidents en usage temporaire. Au-delà du délai, vous risquez une amende de 135 euros et une immobilisation possible.`]},{type:`text`,heading:`Vos deux obligations : assurance et immatriculation`,paragraphs:[`La responsabilité civile est obligatoire dès l'arrivée du véhicule en France. À bord, vous devez pouvoir présenter un justificatif d'assurance couvrant le territoire français et la carte grise étrangère. Rouler sans assurance est un délit (article L324-2), passible d'une amende pouvant atteindre 3 750 euros, avec immobilisation ou confiscation possible.`],relatedLink:{text:`Contrôlé sans assurance : risques, amende et que faire`,href:`/articles/controle-sans-assurance-risques-amende`}},{type:`stepflow`,ariaLabel:`Etapes : véhicule étranger, assurance temporaire, immatriculation sous 1 mois, carte grise française`,steps:[{icon:n,label:`Véhicule étranger`},{icon:a,label:`Assurance temporaire`},{icon:r,label:`Immatriculation sous 1 mois`},{icon:i,label:`Carte grise française`}]},{type:`text`,heading:`Comment s'assurer en attendant l'immatriculation française`,paragraphs:[`L'assurance temporaire est la solution la plus simple : de 1 à 90 jours, elle couvre la responsabilité civile et délivre une attestation immédiate. Elle peut être souscrite à partir de la plaque étrangère si elle est valide, ou du numéro de châssis (VIN) si la plaque n'est plus exploitable. Elle vous laisse le temps d'accomplir les démarches.`]},{type:`text`,heading:`Le retour d'un véhicule acheté à l'étranger`,paragraphs:[`Si vous rapatriez un véhicule acheté à l'étranger, vous pouvez être assuré dès l'étranger, le jour de l'achat ou la veille du rapatriement, pour le ramener légalement. Ensuite, vous disposez de 30 jours pour l'immatriculer en France (contrôle technique si le véhicule a plus de 4 ans, quitus fiscal, demande sur l'ANTS). Une plaque provisoire WW peut alors être délivrée pour la transition.`],relatedLink:{text:`Assurer un véhicule acheté chez un particulier`,href:`/articles/assurer-vehicule-achete-chez-particulier`}},{type:`text`,heading:`Et le permis de conduire étranger ?`,paragraphs:[`Vous pouvez souscrire avec un permis valide et reconnu. Les permis de l'Union européenne sont acceptés ; les permis hors UE le sont sous conditions (durée parfois limitée, âge minimum plus élevé). Le plus sûr est de vérifier votre éligibilité directement au devis ou par téléphone.`]},{type:`checklist`,heading:`Les documents pour souscrire`,items:[`Carte grise étrangère ou preuve de propriété du véhicule`,`Permis de conduire valide et reconnu`,`Pièce d'identité`,`Moyen de paiement (carte bancaire)`],note:`Le numéro de châssis (VIN) peut être demandé si la plaque étrangère n'est pas exploitable.`},{type:`text`,heading:`Qui peut souscrire ?`,paragraphs:[`Sous conditions habituelles (au moins 20 ans, permis depuis plus de 2 ans, profil sans antécédents lourds), et selon le pays d'origine du véhicule et du permis. L'éligibilité s'affiche au devis, et l'équipe répond au téléphone en cas de doute.`]},{type:`text`,heading:`En résumé`,paragraphs:[`Un véhicule étranger se conduit légalement en France à deux conditions : être assuré, et lancer l'immatriculation française dans le mois si vous y résidez. L'assurance temporaire fait le pont, avec une attestation immédiate, le temps de régulariser.`]}],faqItems:[{q:`Peut-on rouler en France avec une plaque étrangère ?`,a:`Oui, temporairement et si vous êtes assuré. Si vous résidez en France, l'immatriculation française est obligatoire dans un délai d'un mois.`},{q:`Combien de temps peut-on garder une plaque étrangère ?`,a:`Jusqu'à un mois pour un résident. Au-delà, vous risquez une amende de 135 euros et devez avoir immatriculé le véhicule.`},{q:`Peut-on assurer un véhicule immatriculé à l'étranger ?`,a:`Oui, via une assurance temporaire de 1 à 90 jours, à partir de la plaque étrangère ou du numéro de châssis.`},{q:`Faut-il un permis français ?`,a:`Non, un permis valide et reconnu suffit. Les permis de l'Union européenne sont acceptés, les permis hors UE sous conditions.`},{q:`Quels documents pour souscrire ?`,a:`Carte grise étrangère ou preuve de propriété, permis valide, pièce d'identité, moyen de paiement.`},{q:`Que risque-t-on sans assurance ?`,a:`Un défaut d'assurance, délit passible d'une amende jusqu'à 3 750 euros, avec immobilisation possible.`}]}}));function f(){return(0,p.jsx)(c,{data:u})}var p;e((()=>{s(),d(),p=t()}))();export{f as default};